// core.d/0000-added-indexes.js — the ADDED_INDEXES baseline, moved verbatim
// out of core.js (BH-8395). FROZEN: do not edit this file. A new index on an
// added column is a NEW file, core.d/<ticket-key>-<name>.js, exporting
// ADDED_INDEXES = { <table>: ["CREATE INDEX IF NOT EXISTS ..."] }; the composer
// (src/lib/core-registries.js) appends it after this baseline.
//
// BH-2489: indexes that name an ADDED column, created by ensureColumns right
// after the ALTER loop, so they exist exactly when their column does. They can
// never live in schema.sql: harness-sync applies that file to the live D1 BEFORE
// the worker deploys, when lane_id does not exist yet, and a CREATE INDEX on it
// there fails "no such column" and wedges every later deploy (#2473; see the
// note under cost_rows' indexes in schema.sql). These two serve the pre-call
// spend gate's GET /api/metrics/llm-spend?lane= read, which runs once per
// registered stage on every capped model call. Same rule as ADDED_COLUMNS:
// literal statements only, never built from a request.
export const ADDED_INDEXES = {
  cost_rows: ["CREATE INDEX IF NOT EXISTS idx_cost_rows_lane_ts ON cost_rows(lane_id, ts)",
              "CREATE INDEX IF NOT EXISTS idx_cost_rows_stage_ts ON cost_rows(stage, ts)"],
  // BH-6971: serves GET /api/alerts?component=<c> and ?unstamped=1 (both
  // ORDER BY last_seen DESC), the groom's read of open rows with no component.
  alerts: ["CREATE INDEX IF NOT EXISTS idx_alerts_component ON alerts(component, last_seen)"],
  // BH-7191 (BH-7302): serves the newest tick per box (WHERE box=? ORDER BY
  // last_tick_at DESC LIMIT 1), the heartbeat read of the fleet version check.
  lane_ticks: ["CREATE INDEX IF NOT EXISTS idx_lane_ticks_box ON lane_ticks(box, last_tick_at)"],
};
